static partial class Art {
    public static SizeF LocalSize(Mark mark){return (mark.Orientation&1)!=0?new SizeF(Math.Abs(mark.H),Math.Abs(mark.W)):new SizeF(Math.Abs(mark.W),Math.Abs(mark.H));}
    public static PointF OrientPoint(PointF point,SizeF size,int orientation){float x=point.X,y=point.Y,w=size.Width,h=size.Height;switch(orientation&3){case 1:point=new PointF(h-y,x);break;case 2:point=new PointF(w-x,h-y);break;case 3:point=new PointF(y,w-x);break;}if((orientation&4)!=0)point.X=((orientation&1)!=0?h:w)-point.X;return point;}
    static Matrix OrientationMatrix(Mark mark){var size=LocalSize(mark);var zero=OrientPoint(PointF.Empty,size,mark.Orientation);var x=OrientPoint(new PointF(1,0),size,mark.Orientation);var y=OrientPoint(new PointF(0,1),size,mark.Orientation);return new Matrix(x.X-zero.X,x.Y-zero.Y,y.X-zero.X,y.Y-zero.Y,mark.BodyBounds.Left+zero.X,mark.BodyBounds.Top+zero.Y);}
    public static PointF LocalPoint(Mark mark,PointF point){using(var matrix=OrientationMatrix(mark)){matrix.Invert();var points=new[]{point};matrix.TransformPoints(points);return points[0];}}
    public static int ComposeOrientation(int previous,int next){var size=new SizeF(10,10);var zero=OrientPoint(OrientPoint(PointF.Empty,size,previous),size,next);var x=OrientPoint(OrientPoint(new PointF(1,0),size,previous),size,next);var y=OrientPoint(OrientPoint(new PointF(0,1),size,previous),size,next);for(int i=0;i<8;i++){var z=OrientPoint(PointF.Empty,size,i);var a=OrientPoint(new PointF(1,0),size,i);var b=OrientPoint(new PointF(0,1),size,i);if(x.X-zero.X==a.X-z.X&&x.Y-zero.Y==a.Y-z.Y&&y.X-zero.X==b.X-z.X&&y.Y-zero.Y==b.Y-z.Y)return i;}throw new InvalidOperationException("Invalid orientation.");}
    static void PaintOriented(Graphics graphics,Bitmap target,Mark mark){var local=mark.Clone();var size=LocalSize(mark);local.Orientation=0;local.X=local.Y=0;local.W=size.Width;local.H=size.Height;var state=graphics.Save();try{using(var matrix=OrientationMatrix(mark))graphics.MultiplyTransform(matrix,MatrixOrder.Prepend);PaintVector(graphics,target,local);}finally{graphics.Restore(state);}}
    static void ApplyGrayscale(Bitmap target,Mark mark,Rectangle? update){
        float amount=Math.Max(0,Math.Min(1,mark.FillOpacity/100));if(amount==0)return;var rect=mark.AdjustmentWholeCanvas?new Rectangle(Point.Empty,target.Size):Rectangle.Intersect(Rectangle.Ceiling(mark.BodyBounds),new Rectangle(Point.Empty,target.Size));if(update.HasValue)rect=Rectangle.Intersect(rect,update.Value);if(rect.Width<1||rect.Height<1)return;
        var bits=target.LockBits(rect,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{int stride=Math.Abs(bits.Stride);var bytes=new byte[stride*rect.Height];Marshal.Copy(bits.Scan0,bytes,0,bytes.Length);for(int y=0;y<rect.Height;y++)for(int x=0;x<rect.Width;x++){int i=y*stride+x*4;int gray=(77*bytes[i+2]+150*bytes[i+1]+29*bytes[i]+128)>>8;for(int c=0;c<3;c++)bytes[i+c]=(byte)Math.Round(bytes[i+c]+(gray-bytes[i+c])*amount);}Marshal.Copy(bytes,0,bits.Scan0,bytes.Length);}finally{target.UnlockBits(bits);}
    }
}
partial class Editor {
    Control adjustmentRow;ThemeCheckBox adjustmentWhole;
    void AddAdjustmentInspector(){var group=new Panel {Width=217,Height=38,Margin=Padding.Empty};adjustmentWhole=new ThemeCheckBox {Text="Entire canvas",Dock=DockStyle.Fill,Width=210,Height=32,ForeColor=text};adjustmentWhole.CheckedChanged+=delegate{if(syncing||Active==null||Active.Kind!="Grayscale")return;Push();Active.AdjustmentWholeCanvas=adjustmentWhole.Checked;if(adjustmentWhole.Checked){Active.X=Active.Y=0;Active.W=Background.Width;Active.H=Background.Height;Active.HasCropClip=false;}RefreshImage();};group.Controls.Add(adjustmentWhole);adjustmentRow=group;inspector.Controls.Add(group);}
    void UpdateAdjustmentInspector(string kind){adjustmentRow.Visible=kind=="Grayscale";if(kind=="Grayscale"){adjustmentWhole.Checked=Active!=null&&Active.AdjustmentWholeCanvas;fillOpacityRow.Controls[0].Text="Effect opacity · %";}}
    void AddGrayscaleAdjustment(){CloseImageEffects();Push();var adjustment=new Mark {Kind="Grayscale",Name="Grayscale adjustment",W=Background.Width,H=Background.Height,Width=0,FillOpacity=100,AdjustmentWholeCanvas=true};Marks.Add(adjustment);Active=adjustment;Selected.Clear();Selected.Add(adjustment);tool="Select";SyncStyle();RefreshImage();}
    void FinishEditableEffect(Rectangle? minimum=null){Active=null;Selected.Clear();Crop=null;if(minimum.HasValue)ReadCanvasBase(minimum.Value);else ResetCanvasBase();SnapshotImageBytes();RefreshImage();View.Fit();}
    static RectangleF MapRect(RectangleF rect,SizeF canvas,int orientation){var points=new[]{rect.Location,new PointF(rect.Right,rect.Top),new PointF(rect.Right,rect.Bottom),new PointF(rect.Left,rect.Bottom)}.Select(p=>Art.OrientPoint(p,canvas,orientation)).ToArray();return RectangleF.FromLTRB(points.Min(p=>p.X),points.Min(p=>p.Y),points.Max(p=>p.X),points.Max(p=>p.Y));}
    void TransformEditableImage(int orientation){
        Push();EndDragPreview();var size=new SizeF(Background.Width,Background.Height);var minimum=Rectangle.Round(MapRect(canvasBase,size,orientation));var next=new Bitmap(Background);next.RotateFlip((RotateFlipType)orientation);Background.Dispose();Background=next;
        foreach(var mark in Marks){var old=mark.Clone();var body=MapRect(old.BodyBounds,size,orientation);if(Art.IsArrow(old.Kind)){var start=Art.OrientPoint(new PointF(old.X,old.Y),size,orientation);var end=Art.OrientPoint(new PointF(old.X+old.W,old.Y+old.H),size,orientation);var zero=Art.OrientPoint(PointF.Empty,size,orientation);var curve=Art.OrientPoint(new PointF(old.CurveX,old.CurveY),size,orientation);mark.X=start.X;mark.Y=start.Y;mark.W=end.X-start.X;mark.H=end.Y-start.Y;mark.CurveX=curve.X-zero.X;mark.CurveY=curve.Y-zero.Y;}
            else {mark.X=body.X;mark.Y=body.Y;mark.W=body.Width;mark.H=body.Height;if(old.Kind!="Pen"&&old.Kind!="Grayscale"&&old.Kind!="Blur"&&old.Kind!="Pixelate"&&old.Kind!="Magnify"&&old.Kind!="Spotlight")mark.Orientation=Art.ComposeOrientation(old.Orientation,orientation);}
            mark.Points=old.Points.Select(point=>Art.OrientPoint(point,size,orientation)).ToList();if(old.SourceInitialized){var source=Art.OrientPoint(new PointF(old.SourceX,old.SourceY),size,orientation);mark.SourceX=source.X;mark.SourceY=source.Y;}if(old.HasCropClip)mark.CropClip=MapRect(old.CropClip,size,orientation);
        }
        FinishEditableEffect(minimum);
    }
    void ResizeEditableImage(Size size){
        if(size==Background.Size)return;Push();float sx=(float)size.Width/Background.Width,sy=(float)size.Height/Background.Height;var next=new Bitmap(size.Width,size.Height,PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(next))Art.DrawImageQuality(graphics,Background,new RectangleF(Point.Empty,size));Background.Dispose();Background=next;
        foreach(var mark in Marks){mark.X*=sx;mark.Y*=sy;mark.W*=sx;mark.H*=sy;mark.CurveX*=sx;mark.CurveY*=sy;mark.SourceX*=sx;mark.SourceY*=sy;float factor=Math.Min(sx,sy);mark.Width*=factor;mark.Size*=factor;mark.Radius*=factor;mark.ShadowSize*=factor;bool swap=(mark.Orientation&1)!=0;mark.TextInsetLeft*=swap?sy:sx;mark.TextInsetRight*=swap?sy:sx;mark.TextInsetTop*=swap?sx:sy;mark.TextInsetBottom*=swap?sx:sy;mark.Points=mark.Points.Select(p=>new PointF(p.X*sx,p.Y*sy)).ToList();if(mark.HasCropClip)mark.CropClip=new RectangleF(mark.CropClip.X*sx,mark.CropClip.Y*sy,mark.CropClip.Width*sx,mark.CropClip.Height*sy);}
        FinishEditableEffect();
    }
    void AddEditableBackdrop(int padding){int width=Background.Width+padding*2,height=Background.Height+padding*2;if(width>16000||height>16000||(long)width*height>40000000)throw new ArgumentException("Canvas size limit exceeded.");Push();var next=new Bitmap(width,height,PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(next)){using(var brush=new LinearGradientBrush(new Rectangle(0,0,width,height),Color.FromArgb(65,87,150),Color.FromArgb(148,113,186),45f))graphics.FillRectangle(brush,0,0,width,height);graphics.DrawImageUnscaled(Background,padding,padding);}Background.Dispose();Background=next;foreach(var mark in Marks){mark.Move(padding,padding);if(mark.SourceInitialized){mark.SourceX+=padding;mark.SourceY+=padding;}}FinishEditableEffect();}
    void AppendEditableImage(Image image){int width=Math.Max(Background.Width,image.Width),height=Background.Height+image.Height;if(width>16000||height>16000||(long)width*height>40000000)throw new ArgumentException("Canvas size limit exceeded.");Push();int y=Background.Height;ResizeCanvas(width,height,0,0);using(var copy=new Bitmap(image)){Marks.Add(new Mark {Kind="Image",Name="Appended image",X=0,Y=y,W=image.Width,H=image.Height,Width=0,Image=Art.Bytes(copy)});}FinishEditableEffect();}
    public void VerifyEditableEffects(List<string> report,string folder){
        Action<bool,string> check=delegate(bool ok,string label){if(!ok)throw new Exception(label);report.Add("PASS "+label);};
        using(var image=Blank(180,120)){using(var g=Graphics.FromImage(image)){g.Clear(Color.CornflowerBlue);g.FillRectangle(Brushes.Red,10,10,50,30);}LoadImageDocument(new Bitmap(image),"Editable effects");}var text=new Mark {Kind="Text",X=70,Y=40,W=90,H=50,Text="Editable",Size=20,Color=Color.Black.ToArgb()};var arrow=new Mark {Kind="Arrow",X=20,Y=80,W=110,H=20,Width=3};Marks.Add(text);Marks.Add(arrow);RefreshImage();var data=Marks[0].Image;var before=Snapshot();
        using(var expected=Art.Render(Background,Marks)){expected.RotateFlip(RotateFlipType.Rotate90FlipNone);TransformEditableImage(1);check(Background.Size==new Size(120,180)&&Marks.Count==3&&Object.ReferenceEquals(data,Marks[0].Image)&&text.Text=="Editable","Rotate preserves editable layers and shares original image bytes");using(var actual=Art.Render(Background,Marks)){check(actual.GetPixel(100,15).ToArgb()==expected.GetPixel(100,15).ToArgb()&&actual.GetPixel(80,15).ToArgb()==expected.GetPixel(80,15).ToArgb(),"Rotated screenshot pixels match raster reference");actual.Save(System.IO.Path.Combine(folder,"editable-rotated.png"));}}
        TransformEditableImage(3);check(Marks[1].Orientation==0&&Math.Abs(Marks[1].X-70)<.01,"Inverse rotation restores text orientation and position");for(int i=0;i<4;i++)TransformEditableImage(1);check(Marks[1].Orientation==0&&Marks[1].W==90,"Four rotations preserve text geometry");TransformEditableImage(4);TransformEditableImage(4);check(Marks[1].Orientation==0&&Marks[1].X==70,"Two horizontal flips restore text and layers");Restore(before);
        ResizeEditableImage(new Size(360,240));check(Marks.Count==3&&Marks[1].Size==40&&Object.ReferenceEquals(data,Marks[0].Image),"Resize scales editable markup without duplicating image data");Undo();check(Background.Size==new Size(180,120)&&Marks.Count==3,"Undo restores resize and all annotations");
        AddEditableBackdrop(20);check(Marks.Count==3&&Marks[1].X==90&&Background.Size==new Size(220,160),"Presentation background retains and offsets editable markup");Undo();using(var appended=Blank(70,40))AppendEditableImage(appended);check(Marks.Count==4&&Marks[3].Kind=="Image"&&Background.Height==160,"Stitch adds an editable image layer");Undo();
        AddGrayscaleAdjustment();var adjustment=Active;check(adjustment.Kind=="Grayscale"&&Marks.Count==4,"Grayscale creates an adjustment layer instead of flattening");check(adjustmentWhole.Checked&&fillOpacity.Value==100,"Grayscale inspector defaults to full canvas at full strength");using(var rendered=Art.Render(Background,Marks)){var pixel=rendered.GetPixel(15,15);check(pixel.R==pixel.G&&pixel.G==pixel.B,"Adjustment affects underlying screenshot");}adjustment.Visible=false;using(var rendered=Art.Render(Background,Marks))check(rendered.GetPixel(15,15).R==255&&rendered.GetPixel(15,15).G==0,"Hiding adjustment restores original colors");adjustment.Visible=true;adjustment.AdjustmentWholeCanvas=false;adjustment.X=10;adjustment.Y=10;adjustment.W=20;adjustment.H=20;
        using(var rendered=Art.Render(Background,Marks)){check(rendered.GetPixel(15,15).R==rendered.GetPixel(15,15).G&&rendered.GetPixel(40,15).G==0,"Resized adjustment affects only its region");}adjustment.FillOpacity=50;using(var rendered=Art.Render(Background,Marks)){var pixel=rendered.GetPixel(15,15);check(pixel.R>pixel.G&&pixel.G>0,"Adjustment opacity blends original and grayscale");}adjustment.FillOpacity=100;Marks.Add(new Mark {Kind="Rectangle",X=10,Y=10,W=20,H=20,Fill=true,FillColor=Color.Lime.ToArgb(),Width=0});using(var rendered=Art.Render(Background,Marks))check(rendered.GetPixel(15,15).G==255&&rendered.GetPixel(15,15).R==0,"Layers above adjustment retain their colors");
        var saved=Snapshot();using(var stream=new System.IO.MemoryStream()){var xml=new System.Xml.Serialization.XmlSerializer(typeof(Project));xml.Serialize(stream,saved);stream.Position=0;Restore((Project)xml.Deserialize(stream));}check(Marks.Any(m=>m.Kind=="Grayscale"&&!m.AdjustmentWholeCanvas),"Adjustment region and strength survive project serialization");Active=Marks.First(mark=>mark.Kind=="Grayscale");SyncStyle();RefreshImage();Show();Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(folder,"adjustment-inspector.png"));}Hide();
        LoadImageDocument(Blank(3840,2160),"4K adjustment benchmark");var movingMark=new Mark {Kind="Rectangle",X=400,Y=400,W=220,H=120,Width=4,Fill=true,FillColor=Color.RoyalBlue.ToArgb()};Marks.Add(movingMark);Marks.Add(new Mark {Kind="Grayscale",W=3840,H=2160,AdjustmentWholeCanvas=true});Active=movingMark;Selected.Clear();Selected.Add(movingMark);RenderPreview(false);var timer=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<2;i++){movingMark.Move(3,2);using(var image=Art.Render(Background,Marks,false)){} }timer.Stop();double full=timer.Elapsed.TotalMilliseconds/2;RenderPreview(false);moving=true;StartDragPreview();var buffer=Preview;timer.Restart();for(int i=0;i<8;i++){movingMark.Move(3,2);TryQueueDragFrame();PrepareDragFrame();}timer.Stop();double incremental=timer.Elapsed.TotalMilliseconds/8;check(Object.ReferenceEquals(buffer,Preview),"4K adjustment dragging reuses the preview buffer");using(var expected=Art.Render(Background,Marks,false)){bool same=true;var rect=Art.DrawingBounds(movingMark,Background.Size);for(int y=rect.Top;y<rect.Bottom&&same;y++)for(int x=rect.Left;x<rect.Right;x++)if(expected.GetPixel(x,y)!=Preview.GetPixel(x,y)){same=false;break;}check(same,"Incremental adjustment compositing matches full render");}moving=false;EndDragPreview();report.Add("4K adjustment benchmark: full redraw "+full.ToString("F2")+" ms/frame; incremental "+incremental.ToString("F2")+" ms/frame.");System.IO.File.WriteAllText(System.IO.Path.Combine(folder,"adjustment-benchmark.txt"),"4K screenshot, colored rectangle, full-canvas grayscale. Compositing only; excludes display latency. Full redraw: "+full.ToString("F2")+" ms/frame. Incremental: "+incremental.ToString("F2")+" ms/frame.");
        LoadBitmap(Blank(100,80),"Rotate automatic margins");var outside=new Mark {Kind="Rectangle",X=80,Y=10,W=80,H=30};Marks.Add(outside);EnsureCanvasFitsMarks();TransformEditableImage(1);outside.H=5;EnsureCanvasFitsMarks();check(Background.Size==new Size(80,100),"Rotation preserves the original canvas minimum so automatic margins can retract");
        LoadBitmap(Blank(100,100),"Test");
    }
}
